 connect(add,&QPushButton::clicked,this,[this]{if(m_parameters->rowCount()>=16){m_status->setText(tr("At most16 runtime parameters are supported."));return;}const auto row=m_parameters->rowCount();m_parameters->insertRow(row);m_parameters->setItem(row,0,new QTableWidgetItem(QStringLiteral("real")));m_parameters->setItem(row,1,new QTableWidgetItem(QStringLiteral("parameter%1").arg(row+1)));m_parameters->setItem(row,2,new QTableWidgetItem(QStringLiteral("1.0")));});
